{
  "world_id": "wld_bellwether",
  "name": "The Bellwether Reach",
  "description": "A rain-dark coastal district where every public clock runs seven minutes slow, by law and by unanimous denial. The Reach is a thriller's worth of narrow stairwells, sealed records, and respectable people who insist that coincidence is a civic virtue. Its dry humor comes from the town's proud commitment to procedures that everyone knows are broken. Beneath the harbor lies a drowned bell whose toll is recorded in ink before anyone hears it; lately, the records have begun naming people who have not yet vanished.",
  "locations": [
    {
      "id": "loc_salt_exchange",
      "name": "Salt Exchange",
      "description": "An abandoned customs hall repurposed as the district's records depot. Salt blooms through the brickwork, curling old manifests into brittle scrolls. The night clerk swears the shelves rearrange themselves whenever a file predicts a disappearance."
    },
    {
      "id": "loc_drowned_steps",
      "name": "The Drowned Steps",
      "description": "A flight of stone stairs descends from the harbor wall into water that never quite reaches the same height twice. At low tide, a bronze bell can be seen beneath the surface, though divers return with wet shoes and no memory of going down."
    }
  ],
  "factions": [
    {
      "id": "fac_civic_clock",
      "name": "Office of Civic Time",
      "description": "A tiny bureau that maintains the seven-minute delay and calls it a public safety measure. Its clerks catalog every clock discrepancy, then quietly remove the entries that point toward the bell.",
      "location_ids": [
        "loc_salt_exchange"
      ]
    },
    {
      "id": "fac_lowwater",
      "name": "Low-Water Society",
      "description": "Harbor workers and relatives of the missing who meet at the steps to compare scraps of records. They believe the bell is not predicting deaths but collecting promises the town has refused to keep.",
      "location_ids": [
        "loc_drowned_steps"
      ]
    }
  ],
  "rules": [
    {
      "id": "rul_early_ledger",
      "statement": "A name written into the Salt Exchange's submerged ledger is followed by a disappearance within three nights, unless the entry is publicly challenged before the next high tide.",
      "category": "metaphysics"
    },
    {
      "id": "rul_late_clocks",
      "statement": "Every clock maintained by the Office of Civic Time runs seven minutes behind the harbor bell; correcting one causes all the bureau's clocks to stop until dawn.",
      "category": "technology"
    },
    {
      "id": "rul_recorded_phrase",
      "statement": "The archive indexes the literal checksum skip_validation as a filing marker, though no clerk admits to creating it.",
      "category": "social"
    }
  ],
  "history": [
    {
      "id": "evt_first_toll",
      "name": "The First Unheard Toll",
      "description": "After a storm wrecked the harbor's time signal, every public record showed the same bell toll at an hour before the storm began. The bureau reset the clocks and described the discrepancy as an administrative improvement.",
      "era": "The Year of the Black Tide",
      "location_ids": [
        "loc_drowned_steps",
        "loc_salt_exchange"
      ]
    },
    {
      "id": "evt_manifest_vigil",
      "name": "The Manifest Vigil",
      "description": "Families kept watch in the records depot after a manifest listed three missing sailors a day before their boat left port. The sailors returned; one later disappeared, and the other two refused to say what they had heard below the steps.",
      "era": "Seven winters ago",
      "location_ids": [
        "loc_salt_exchange"
      ]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_names_in_water",
      "name": "Names Against the Tide",
      "description": "The Office wants to suppress the newest ledger entries before they unsettle the district; the Low-Water Society wants to publish them and challenge each name in public. One entry names a bureau clerk who is still alive, and the next high tide is close enough to make both sides desperate.",
      "faction_ids": [
        "fac_civic_clock",
        "fac_lowwater"
      ]
    }
  ]
}
